import run.halo.app.core.extension.content.Reply;
import run.halo.app.core.user.service.UserService;
import run.halo.app.extension.*;
import run.halo.app.infra.AnonymousUserConst;
import run.halo.app.infra.exception.UnsatisfiedAttributeValueException;
import run.halo.app.infra.utils.JsonUtils;
import run.halo.app.theme.finders.CommentPublicQueryService;
import run.halo.app.theme.finders.vo.*;

/**
 * comment public query service implementation.
 *
 * @author LIlGG
 * @author guqing
 */
@Component
@RequiredArgsConstructor
public class CommentPublicQueryServiceImpl implements CommentPublicQueryService {
    private static final int DEFAULT_SIZE = 10;

    private static final String COMMENT_VIEW_PERMISSION = "role-template-view-comments";

    private final ReactiveExtensionClient client;
    private final UserService userService;
    private final CounterService counterService;
    private final CommentPermalinkService permalinkService;

    @Override
    public Mono<CommentVo> getByName(String name) {
        return getVisibleComment(name).flatMap(this::toCommentVoWithPermalink);
    }

    private Mono<CommentVo> toCommentVoWithPermalink(Comment comment) {
        return toCommentVo(comment)
                .flatMap(vo -> permalinkService
                        .getPermalink(comment)
                        .doOnNext(vo::setPermalink)
                        .thenReturn(vo));
    }

    private Mono<Comment> getVisibleComment(String name) {
        return populateVisibleListOptions(null)
                .map(builder -> builder.andQuery(equal("metadata.name", name)).build())
                .flatMap(options -> client.listBy(Comment.class, options, PageRequestImpl.ofSize(1)))
                .flatMapIterable(ListResult::getItems)
                .next();
    }

    @Override
    public Mono<ReplyVo> getReply(String commentName, String replyName) {
        return getVisibleComment(commentName)
                .flatMap(comment -> populateReplyListOptions(comment)
                        .doOnNext(options -> options.setFieldSelector(
                                options.getFieldSelector().andQuery(equal("metadata.name", replyName))))
                        .flatMap(options -> client.listBy(Reply.class, options, PageRequestImpl.ofSize(1)))
                        .flatMapIterable(ListResult::getItems)
                        .next()
                        .flatMap(this::toReplyVo)
                        .flatMap(vo -> permalinkService
                                .getSubjectUrl(comment.getSpec().getSubjectRef())
                                .doOnNext(url -> vo.setPermalink(
                                        CommentPermalinkService.getPermalink(url, commentName, replyName)))
                                .thenReturn(vo)));
    }

    @Override
    public Mono<ListResult<CommentVo>> list(Ref ref, Integer page, Integer size) {
        return list(ref, PageRequestImpl.of(pageNullSafe(page), sizeNullSafe(size), defaultCommentSort()));
    }

    @Override
    public Mono<ListResult<CommentVo>> list(Ref ref, PageRequest pageParam) {
        var pageRequest = Optional.ofNullable(pageParam)
                .map(page -> page.withSort(page.getSort().and(defaultCommentSort())))
                .orElseGet(() -> PageRequestImpl.ofSize(10));
        return populateCommentListOptions(ref)
                .flatMap(listOptions -> client.listBy(Comment.class, listOptions, pageRequest))
                .flatMap(listResult -> permalinkService
                        .getSubjectUrl(ref)
                        .defaultIfEmpty("")
                        .flatMap(subjectUrl -> Flux.fromStream(listResult.get())
                                .map(comment -> ref == null ? toCommentVoWithPermalink(comment) : toCommentVo(comment))
                                .flatMapSequential(Function.identity())
                                .doOnNext(vo -> {
                                    if (ref != null) {
                                        vo.setPermalink(CommentPermalinkService.getPermalink(
                                                subjectUrl, vo.getMetadata().getName(), null));
                                    }
                                })
                                .collectList()
                                .map(commentVos -> new ListResult<>(
                                        listResult.getPage(),
                                        listResult.getSize(),
                                        listResult.getTotal(),
                                        commentVos))))
                .defaultIfEmpty(ListResult.emptyResult());
    }

    @Override
    public Mono<ListResult<CommentWithReplyVo>> convertToWithReplyVo(ListResult<CommentVo> comments, int replySize) {
        return Flux.fromIterable(comments.getItems())
                .flatMapSequential(commentVo -> {
                    var commentName = commentVo.getMetadata().getName();
                    return listReply(commentName, 1, replySize)
                            .map(replyList -> CommentWithReplyVo.from(commentVo).setReplies(replyList));
                })
                .collectList()
                .map(result -> new ListResult<>(comments.getPage(), comments.getSize(), comments.getTotal(), result));
    }

    @Override
    public Mono<ListResult<ReplyVo>> listReply(String commentName, Integer page, Integer size) {
        return listReply(commentName, PageRequestImpl.of(pageNullSafe(page), sizeNullSafe(size), defaultReplySort()));
    }

    @Override
    public Mono<ListResult<ReplyVo>> listReply(String commentName, PageRequest pageParam) {
        // check comment
        return client.get(Comment.class, commentName)
                .flatMap(comment -> populateReplyListOptions(comment).flatMap(listOptions -> {
                    var pageRequest = Optional.ofNullable(pageParam)
                            .map(page -> page.withSort(page.getSort().and(defaultReplySort())))
                            .orElseGet(() -> PageRequestImpl.ofSize(PageRequestImpl.MAX_SIZE));
                    return client.listBy(Reply.class, listOptions, pageRequest)
                            .flatMap(list -> permalinkService
                                    .getSubjectUrl(comment.getSpec().getSubjectRef())
                                    .defaultIfEmpty("")
                                    .flatMap(subjectUrl -> Flux.fromStream(
                                                    list.get().map(this::toReplyVo))
                                            .flatMapSequential(Function.identity())
                                            .doOnNext(vo -> vo.setPermalink(CommentPermalinkService.getPermalink(
                                                    subjectUrl,
                                                    commentName,
                                                    vo.getMetadata().getName())))
                                            .collectList()
                                            .map(replyVos -> new ListResult<>(
                                                    list.getPage(), list.getSize(), list.getTotal(), replyVos))));
                }))
                .defaultIfEmpty(ListResult.emptyResult());
    }

    Mono<CommentVo> toCommentVo(Comment comment) {
        Comment.CommentOwner owner = comment.getSpec().getOwner();
        return Mono.just(CommentVo.from(JsonUtils.deepCopy(comment)))
                .flatMap(commentVo -> populateStats(Comment.class, commentVo)
                        .doOnNext(commentVo::setStats)
                        .thenReturn(commentVo))
                .flatMap(commentVo ->
                        getOwnerInfo(owner).doOnNext(commentVo::setOwner).thenReturn(commentVo))
                .flatMap(this::filterCommentSensitiveData);
    }

    private Mono<? extends CommentVo> filterCommentSensitiveData(CommentVo commentVo) {
        var status = commentVo.getStatus();
        if (status != null) {
            var publicStatus = new Comment.CommentStatus();
            publicStatus.setVisibleReplyCount(status.getVisibleReplyCount());
            publicStatus.setReplyCount(status.getVisibleReplyCount());
            if (status.getReplyCount() != null && status.getReplyCount().equals(status.getVisibleReplyCount())) {
                publicStatus.setLastReplyTime(status.getLastReplyTime());
            }
            commentVo.setStatus(publicStatus);
        }
        var owner = commentVo.getOwner();
        commentVo.setOwner(OwnerInfo.builder()
                .displayName(owner.getDisplayName())
                .avatar(owner.getAvatar())
                .kind(owner.getKind())
                .build());

        commentVo.getSpec().setIpAddress("");
        var specOwner = commentVo.getSpec().getOwner();
        specOwner.setName("");
        var email = owner.getEmail();
        if (StringUtils.isNotBlank(email)) {
            var emailHash =
                    Hashing.sha256().hashString(email.toLowerCase(), UTF_8).toString();
            if (specOwner.getAnnotations() == null) {
                specOwner.setAnnotations(new HashMap<>(2));
            }
            specOwner.getAnnotations().put(Comment.CommentOwner.EMAIL_HASH_ANNO, emailHash);
        }
        if (specOwner.getAnnotations() != null) {
            specOwner.getAnnotations().remove("Email");
        }
        return Mono.just(commentVo);
    }

    // @formatter:off
    private <E extends AbstractExtension, T extends ExtensionVoOperator> Mono<CommentStatsVo> populateStats(
            Class<E> clazz, T vo) {
        return counterService
                .getByName(MeterUtils.nameOf(clazz, vo.getMetadata().getName()))
                .map(counter ->
                        CommentStatsVo.builder().upvote(counter.getUpvote()).build())
                .defaultIfEmpty(CommentStatsVo.empty());
    }
    // @formatter:on

    Mono<ReplyVo> toReplyVo(Reply reply) {
        return Mono.just(ReplyVo.from(JsonUtils.deepCopy(reply)))
                .flatMap(replyVo -> populateStats(Reply.class, replyVo)
                        .doOnNext(replyVo::setStats)
                        .thenReturn(replyVo))
                .flatMap(replyVo -> getOwnerInfo(reply.getSpec().getOwner())
                        .doOnNext(replyVo::setOwner)
                        .thenReturn(replyVo))
                .flatMap(this::filterReplySensitiveData);
    }

    private Mono<? extends ReplyVo> filterReplySensitiveData(ReplyVo replyVo) {
        var owner = replyVo.getOwner();
        replyVo.setOwner(OwnerInfo.builder()
                .displayName(owner.getDisplayName())
                .avatar(owner.getAvatar())
                .kind(owner.getKind())
                .build());

        replyVo.getSpec().setIpAddress("");
        var specOwner = replyVo.getSpec().getOwner();
        specOwner.setName("");
        var annotations = new HashMap<String, String>();
        for (var key : Set.of(Comment.CommentOwner.WEBSITE_ANNO, Comment.CommentOwner.AVATAR_ANNO)) {
            var value = specOwner.getAnnotation(key);
            if (value != null) {
                annotations.put(key, value);
            }
        }
        specOwner.setAnnotations(annotations);
        var email = owner.getEmail();
        if (StringUtils.isNotBlank(email)) {
            var emailHash =
                    Hashing.sha256().hashString(email.toLowerCase(), UTF_8).toString();
            annotations.put(Comment.CommentOwner.EMAIL_HASH_ANNO, emailHash);
        }
        return Mono.just(replyVo);
    }

    private Mono<OwnerInfo> getOwnerInfo(Comment.CommentOwner owner) {
        if (Comment.CommentOwner.KIND_EMAIL.equals(owner.getKind())) {
            return Mono.just(OwnerInfo.from(owner));
        }
        return userService.getUserOrGhost(owner.getName()).map(OwnerInfo::from);
    }

    private Mono<ListOptions> populateCommentListOptions(@Nullable Ref ref) {
        return populateVisibleListOptions(null)
                .doOnNext(builder -> {
                    if (ref != null) {
                        builder.andQuery(equal("spec.subjectRef", Comment.toSubjectRefKey(ref)));
                    }
                })
                .map(ListOptions.ListOptionsBuilder::build);
    }

    private Mono<ListOptions.ListOptionsBuilder> populateVisibleListOptions(@Nullable Comment comment) {
        return ReactiveSecurityContextHolder.getContext()
                .map(SecurityContext::getAuthentication)
                .map(Authentication::getName)
                .defaultIfEmpty(AnonymousUserConst.PRINCIPAL)
                .zipWith(userService
                        .hasSufficientRoles(Set.of(COMMENT_VIEW_PERMISSION))
                        .defaultIfEmpty(false))
                .flatMap(tuple2 -> {
                    var username = tuple2.getT1();
                    var hasViewPermission = tuple2.getT2();
                    var commentHidden = false;
                    var isCommentOwner = false;
                    if (comment != null) {
                        commentHidden = Boolean.TRUE.equals(comment.getSpec().getHidden());
                        var owner = comment.getSpec().getOwner();
                        isCommentOwner = owner != null
                                && Objects.equals(
                                        ownerIdentity(owner.getKind(), owner.getName()),
                                        ownerIdentity(User.KIND, username));
                        boolean hasPermission = (!commentHidden
                                        && Boolean.TRUE.equals(comment.getSpec().getApproved()))
                                || hasViewPermission
                                || isCommentOwner;
                        if (ExtensionUtil.isDeleted(comment) || !hasPermission) {
                            return Mono.error(
                                    new UnsatisfiedAttributeValueException("problemDetail.comment.unavailable"));
                        }
                    }

                    var builder = ListOptions.builder();
                    builder.andQuery(isNull("metadata.deletionTimestamp"));
                    var visibleQuery =
                            and(equal("spec.hidden", BooleanUtils.FALSE), equal("spec.approved", BooleanUtils.TRUE));

                    var isAnonymous = AnonymousUserConst.isAnonymousUser(username);
                    if (isAnonymous) {
                        builder.andQuery(visibleQuery);
                    } else if (!hasViewPermission && comment == null) {
                        builder.andQuery(or(visibleQuery, equal("spec.owner", ownerIdentity(User.KIND, username))));
                    } else if (!hasViewPermission) {
                        var ownedReplies = ListOptions.builder()
                                .andQuery(equal("spec.owner", ownerIdentity(User.KIND, username)))
                                .andQuery(isNull("metadata.deletionTimestamp"))
                                .build();
                        var commentOwner = isCommentOwner;
                        return client.listAllNames(Reply.class, ownedReplies, Sort.unsorted())
                                .collectList()
                                .map(names -> {
                                    var allowed =
                                            or(visibleQuery, equal("spec.owner", ownerIdentity(User.KIND, username)));
                                    if (commentOwner) {
                                        allowed = or(
                                                allowed,
                                                and(
                                                        equal("spec.approved", BooleanUtils.TRUE),
                                                        isNull("spec.quoteReply")));
                                    }
                                    if (!names.isEmpty()) {
                                        allowed = or(
                                                allowed,
                                                and(
                                                        equal("spec.approved", BooleanUtils.TRUE),
                                                        in("spec.quoteReply", names)));
                                    }
                                    builder.andQuery(allowed);
                                    return builder;
                                });
                    }
                    return Mono.just(builder);
                });
    }

    private Mono<ListOptions> populateReplyListOptions(Comment comment) {
        // The comment name must be equal to the comment name of the reply
        // is approved and not hidden
        return populateVisibleListOptions(comment)
                .doOnNext(builder -> builder.andQuery(
                        equal("spec.commentName", comment.getMetadata().getName())))
                .map(ListOptions.ListOptionsBuilder::build);
    }

    static Sort defaultCommentSort() {
        return Sort.by(
                Sort.Order.desc("spec.top"),
                Sort.Order.asc("spec.priority"),
                Sort.Order.desc("spec.creationTime"),
                Sort.Order.asc("metadata.name"));
    }

    static Sort defaultReplySort() {
        return Sort.by(
                Sort.Order.desc("spec.top"),
                Sort.Order.asc("spec.priority"),
                Sort.Order.asc("spec.creationTime"),
                Sort.Order.asc("metadata.name"));
    }

    int pageNullSafe(Integer page) {
        return defaultIfNull(page, 1);
    }

    int sizeNullSafe(Integer size) {
        return defaultIfNull(size, DEFAULT_SIZE);
    }
}

